import * as THREE from 'three';
import { createScene } from './data/object.js';
import fs from 'fs';
import path from 'path';

// Helper function to convert THREE geometry to OBJ data
function geometryToOBJ(geometry, matrix = new THREE.Matrix4()) {
  const vertices = [];
  const normals = [];
  const faces = [];

  // Get position attribute
  const posAttribute = geometry.getAttribute('position');
  if (!posAttribute) return { vertices: [], normals: [], faces: [] };

  // Apply matrix transformation to all vertices
  const positionArray = posAttribute.array;
  const v3 = new THREE.Vector3();

  for (let i = 0; i < positionArray.length; i += 3) {
    v3.set(positionArray[i], positionArray[i + 1], positionArray[i + 2]);
    v3.applyMatrix4(matrix);
    vertices.push([v3.x, v3.y, v3.z]);
  }

  // Get normal attribute if available
  const normAttribute = geometry.getAttribute('normal');
  if (normAttribute) {
    const normArray = normAttribute.array;
    for (let i = 0; i < normArray.length; i += 3) {
      const n3 = new THREE.Vector3(normArray[i], normArray[i + 1], normArray[i + 2]);
      // Apply matrix rotation to normals (without translation)
      const rotMatrix = new THREE.Matrix4();
      rotMatrix.extractRotation(matrix);
      n3.applyMatrix4(rotMatrix);
      normals.push([n3.x, n3.y, n3.z]);
    }
  }

  // Get indices or use sequential indices
  const indexAttr = geometry.getIndex();
  let indices = [];

  if (indexAttr) {
    indices = Array.from(indexAttr.array);
  } else {
    indices = Array.from({ length: positionArray.length / 3 }, (_, i) => i);
  }

  // Create faces (convert to 1-indexed for OBJ format)
  for (let i = 0; i < indices.length; i += 3) {
    const a = indices[i] + 1;
    const b = indices[i + 1] + 1;
    const c = indices[i + 2] + 1;

    let faceStr = `f ${a}`;
    if (normals.length > 0) {
      faceStr += `/${a}/${a}`;
    }
    faceStr += ` ${b}`;
    if (normals.length > 0) {
      faceStr += `/${b}/${b}`;
    }
    faceStr += ` ${c}`;
    if (normals.length > 0) {
      faceStr += `/${c}/${c}`;
    }

    faces.push(faceStr);
  }

  return { vertices, normals, faces };
}

// Traverse scene and collect all meshes with their world matrices
function collectMeshes(object, meshList = [], worldMatrix = new THREE.Matrix4()) {
  const currentMatrix = new THREE.Matrix4();
  object.updateMatrix();
  currentMatrix.multiplyMatrices(worldMatrix, object.matrix);

  if (object.isMesh) {
    meshList.push({
      name: object.name || 'mesh',
      geometry: object.geometry,
      matrix: currentMatrix.clone(),
    });
  }

  // Handle InstancedMesh
  if (object.isInstancedMesh) {
    const geometry = object.geometry;
    const count = object.count;
    const tempMatrix = new THREE.Matrix4();

    for (let i = 0; i < count; i++) {
      object.getMatrixAt(i, tempMatrix);
      const instanceMatrix = new THREE.Matrix4();
      instanceMatrix.multiplyMatrices(currentMatrix, tempMatrix);

      meshList.push({
        name: `${object.name || 'instance'}_${i}`,
        geometry: geometry,
        matrix: instanceMatrix.clone(),
      });
    }
  }

  for (const child of object.children) {
    collectMeshes(child, meshList, currentMatrix);
  }

  return meshList;
}

// Main export function
function exportToOBJ() {
  console.log('Creating scene...');
  const scene = createScene();

  // Create the -90 degree X-rotation matrix (Blender Z-up conversion)
  const blenderMatrix = new THREE.Matrix4();
  blenderMatrix.makeRotationX(-Math.PI / 2);

  console.log('Collecting meshes...');
  const meshes = collectMeshes(scene, [], blenderMatrix);

  // Consolidate OBJ data
  let vertexOffset = 0;
  let normalOffset = 0;
  let objContent = '# Converted from Three.js\n';
  objContent += '# Blender Z-up space (-90° X-rotation applied)\n\n';

  for (const mesh of meshes) {
    if (!mesh.geometry) continue;

    console.log(`Processing mesh: ${mesh.name}`);

    const { vertices, normals, faces } = geometryToOBJ(mesh.geometry, mesh.matrix);

    if (vertices.length === 0) continue;

    objContent += `\n# Object: ${mesh.name}\n`;
    objContent += `g ${mesh.name}\n`;

    // Write vertices
    for (const [x, y, z] of vertices) {
      objContent += `v ${x.toFixed(6)} ${y.toFixed(6)} ${z.toFixed(6)}\n`;
    }

    // Write normals
    for (const [x, y, z] of normals) {
      objContent += `vn ${x.toFixed(6)} ${y.toFixed(6)} ${z.toFixed(6)}\n`;
    }

    // Write faces
    for (const face of faces) {
      objContent += face + '\n';
    }

    vertexOffset += vertices.length;
    normalOffset += normals.length;
  }

  // Ensure output directory exists
  const outputDir = '/root/output';
  if (!fs.existsSync(outputDir)) {
    fs.mkdirSync(outputDir, { recursive: true });
  }

  // Write OBJ file
  const outputPath = path.join(outputDir, 'object.obj');
  fs.writeFileSync(outputPath, objContent, 'utf-8');

  console.log(`✓ OBJ file exported successfully to: ${outputPath}`);
  console.log(`  Total meshes processed: ${meshes.length}`);
  console.log(`  Total vertices: ${vertexOffset}`);
}

// Run export
exportToOBJ();

